-- Classic Recruitment › the pachanga zones of the Chronicle board, script side.
-- Data: every active mod's content\pachangas\*.toml (schema ClassicRecruitment.pachangas/1; this module's zones.toml is
-- generated by research/scripts/classic_recruitment_friendly_zones.py): [[ClassicRecruitment.PachangaZone]] (a board node, its
-- title, its Chronicle match, its stadium) and [[ClassicRecruitment.Pachanga]] (a 5v5 friendly of a zone: its rival team,
-- level, format, its players' cards). A pachanga is only a match: the armed one's result is the game's own (VRFW
-- lib/match_result, signal vrfw.match_result: penalties and forfeits included); an abandoned match (the game sends no
-- result), a loss or a draw counts for nothing. Game Lua side:
-- assets\lua\vs_route_town_menu\new_recruitment_pachangas.lua.
-- | Command | Args | Returns |
-- |---|---|---|
-- | CMND_CLASSICRECRUITMENT_PACHANGA_ZONE | node name | zone index, title text id, stadium map crc, pachanga count (nothing = no zone) |
-- | CMND_CLASSICRECRUITMENT_PACHANGA_GET | zone index, i (1-based) | key, rival team crc, team name, level, format, won (bool), card count, cards… |
-- | CMND_CLASSICRECRUITMENT_PACHANGA_ARM | key | true: the next match is that pachanga's |
-- | CMND_CLASSICRECRUITMENT_PACHANGA_RESULT | — | key, won (bool) of the last armed pachanga's match; nothing = none (read once) |
-- | CMND_CLASSICRECRUITMENT_PACHANGA_WON | key | true when the pachanga was won in this save slot |
-- | CMND_CLASSICRECRUITMENT_PACHANGA_SET_WON | key | true |
-- | CMND_CLASSICRECRUITMENT_PACHANGA_BASE | team level | true: the base the pachangas' levels scale from (the list opens) |
-- | CMND_CLASSICRECRUITMENT_PACHANGA_LEVEL | key | its level now, the friendly's row level (the members' offsets base) |
-- | CMND_CLASSICRECRUITMENT_PACHANGA_MENU | zone index, i | the pose row screen's page: i = 0 the header, i >= 1 pachanga i |

ClassicRecruitment = ClassicRecruitment or {}
local P = {}

local FOLDER = "content/pachangas"
require "VRFW/lib/basics"
local info, warn = VRFW.logger("pachangas")

local crc = VRFW.crc32

local ZONES = nil      -- { { name, node, title, stadium, pachangas = { … } } … }
local LEVEL = { scale = "data", min = 1, max = 200, row_level = 0 }   -- zones.toml [ClassicRecruitment.PachangaLevel]
local BASE = nil       -- the player's team level the levels scale from (CMND_CLASSICRECRUITMENT_PACHANGA_BASE)
local BY_NODE = {}     -- node name -> zone index
local BY_KEY = {}      -- pachanga key -> pachanga
local LIVE = nil       -- the armed pachanga's match: { key, armed, result }
local PLAYED = nil     -- { key, won } until read

local function id_of(text)
  if type(text) == "number" then return math.floor(text) % 4294967296 end
  if type(text) ~= "string" then return nil end
  local h = text:match("^%s*0[xX](%x+)%s*$")
  return h and tonumber(h, 16) or nil
end

local function load_zones()
  if ZONES ~= nil then return ZONES end
  ZONES = {}
  local ok, files = pcall(VRFW.files.declarations, FOLDER)
  if not ok then
    warn("the pachanga zones could not be read (" .. tostring(files) .. "): none")
    return ZONES
  end
  local by_zone, pending = {}, {}
  for _, file in ipairs(type(files) == "table" and files or {}) do
    local root = type(file.data) == "table" and file.data.ClassicRecruitment or nil
    if type(root) == "table" then
      if type(root.PachangaLevel) == "table" then
        local l = root.PachangaLevel
        LEVEL = { scale = tostring(l.scale or "data"), min = math.floor(tonumber(l.min) or 1),
                  max = math.floor(tonumber(l.max) or 200), row_level = math.floor(tonumber(l.row_level) or 0) }
      end
      for _, z in ipairs(root.PachangaZone or {}) do
        if type(z.name) == "string" and type(z.node) == "string" and by_zone[z.name] == nil then
          local zone = { name = z.name, node = z.node, title = crc(tostring(z.title or "")),
                         stadium = crc(tostring(z.stadium or "")), pachangas = {} }
          ZONES[#ZONES + 1] = zone
          by_zone[z.name] = zone
          BY_NODE[z.node] = #ZONES
        end
      end
      for _, p in ipairs(root.Pachanga or {}) do
        pending[#pending + 1] = { file = file, p = p }
      end
    end
  end
  for _, item in ipairs(pending) do
    local file, p = item.file, item.p
    local zone = by_zone[p.zone]
    if zone == nil or type(p.name) ~= "string" or type(p.team) ~= "string" then
      warn(string.format("mods/%s/%s: pachanga %s: unknown zone %s or no team: left out", tostring(file.mod),
        tostring(file.file), tostring(p.name), tostring(p.zone)))
    else
      local cards = {}
      for _, c in ipairs(type(p.cards) == "table" and p.cards or {}) do
        local id = id_of(c)
        if id then cards[#cards + 1] = id end
      end
      local key = file.mod .. "." .. p.name
      local entry = { key = key, team = crc("evt_" .. p.team), team_name = tostring(p.team_name or p.name),
                      level = math.floor(tonumber(p.level) or 1), format = tostring(p.format or "5v5"),
                      level_offset = math.floor(tonumber(p.level_offset) or 0), cards = cards }
      zone.pachangas[#zone.pachangas + 1] = entry
      BY_KEY[key] = entry
    end
  end
  local n = 0
  for _, z in ipairs(ZONES) do n = n + #z.pachangas end
  info(string.format("%d zone(s), %d pachanga(s)", #ZONES, n))
  return ZONES
end

-- a pachanga's level now: the team level + its offset (scale "team", once the list gave the base), else its data level
local function level_of(p)
  local lv = p.level
  if LEVEL.scale == "team" and BASE ~= nil then
    lv = BASE + p.level_offset
  end
  return math.max(LEVEL.min, math.min(LEVEL.max, lv))
end

local function won(key)
  return VRFW.save.get("won." .. key, false) == true
end

function P.Zone(node)
  load_zones()
  local i = BY_NODE[tostring(node)]
  local z = i and ZONES[i]
  if not z then return nil end
  return i, z.title, z.stadium, #z.pachangas
end

function P.Get(zi, i)
  local z = load_zones()[math.floor(tonumber(zi) or 0)]
  local p = z and z.pachangas[math.floor(tonumber(i) or 0)]
  if not p then return nil end
  return p.key, p.team, p.team_name, level_of(p), p.format, won(p.key), #p.cards, table.unpack(p.cards)
end

-- the pachanga list's page of the framework's pose row screen (content\pose_rows\pachangas.toml): i = 0 the header
-- (zone title, count), i >= 1 pachanga i (team, level, each player's card)
local TEXT = {
  COUNT = crc("new_recruitment_pachangas_count"), ROW = crc("new_recruitment_pachangas_row"),
  INFO = crc("new_recruitment_pachangas_info_5v5"), TAG = crc("new_recruitment_pachangas_tag_5v5"),
}
function P.Menu(zi, i)
  local z = load_zones()[math.floor(tonumber(zi) or 0)]
  if not z then return nil end
  i = math.floor(tonumber(i) or 0)
  if i == 0 then
    return { title = z.title, count = #z.pachangas, info = { id = TEXT.COUNT, args = { #z.pachangas } } }
  end
  local p = z.pachangas[i]
  if not p then return nil end
  local models = {}
  for n, card in ipairs(p.cards) do
    models[n] = { card = card, plays = true, no_check = true, text = "" }
  end
  local lv = level_of(p)
  return { label = p.team_name, title = p.team_name, tag = TEXT.TAG, level = lv, done = won(p.key), team = p.team,
           sub = { id = TEXT.ROW, args = { lv } }, info = { id = TEXT.INFO, args = { lv } },
           lineup = #p.cards, models = models }
end

-- ------------------------------------------------------------------------------------------------ the match
function P.Arm(key)
  load_zones()
  local p = BY_KEY[tostring(key)]
  if p == nil then return false end
  LIVE = { key = p.key, armed = true }
  PLAYED = nil
  info("armed " .. p.key)
  return true
end

VRFW.on("match_start", function(ev)
  if LIVE and LIVE.armed then
    LIVE.armed = false
  elseif LIVE then
    LIVE = nil                                     -- another match: the armed pachanga was not played
  end
  return nil
end)

-- the game's own result (VRFW lib/match_result), published before or after match_end: onto the running pachanga, or
-- onto the one just played when match_end came first
VRFW.on("signal:vrfw.match_result", function()
  local last = require("VRFW/lib/match_result").last()
  if type(last) ~= "table" then return nil end
  if LIVE and not LIVE.armed then
    LIVE.result = last
  elseif PLAYED then
    PLAYED.won = last.outcome == "win"
    info(string.format("%s judged: %s", PLAYED.key, tostring(last.outcome)))
  end
  return nil
end)

VRFW.on("match_end", function(ev)
  if not LIVE or LIVE.armed then return nil end
  PLAYED = { key = LIVE.key, won = LIVE.result ~= nil and LIVE.result.outcome == "win" }
  LIVE = nil
  return nil
end)

function P.Result()
  local r = PLAYED
  PLAYED = nil
  if not r then return nil end
  return r.key, r.won
end

function P.Won(key) return won(tostring(key)) end

function P.Base(level)
  load_zones()
  local lv = math.floor(tonumber(level) or 0)
  BASE = lv >= 1 and lv or nil
  return true
end

function P.Level(key)
  load_zones()
  local p = BY_KEY[tostring(key)]
  if not p then return nil end
  return level_of(p), LEVEL.row_level
end

function P.SetWon(key)
  VRFW.save.set("won." .. tostring(key), true)
  return true
end

-- the commands (content\game\pachangas.toml)
ClassicRecruitment.PachangaZone = P.Zone
ClassicRecruitment.PachangaGet = P.Get
ClassicRecruitment.PachangaArm = P.Arm
ClassicRecruitment.PachangaResult = P.Result
ClassicRecruitment.PachangaWon = P.Won
ClassicRecruitment.PachangaSetWon = P.SetWon
ClassicRecruitment.PachangaMenu = P.Menu
ClassicRecruitment.PachangaBase = P.Base
ClassicRecruitment.PachangaLevel = P.Level

pcall(load_zones)
